<script setup>
// Event sign-up form. Mounted once by Layout.vue. It only shows up on pages whose
// frontmatter carries `registration.events` (generated by createFiles.js for events
// with the `registration` switch). `?register[=<event id>]` opens it, and the link in
// the confirmation email (`?edit=<id>.<secret>`) opens it to edit/cancel.
// Spam protection: Cloudflare Turnstile (explicit render, action "register"); the
// token is verified server-side by config-api.
import { ref, computed, onMounted, onBeforeUnmount, nextTick, watch } from "vue";
import { useData } from "vitepress";
import { registrationLabels } from "../../registrationLabels.js";

const { frontmatter, lang } = useData();
const REG = __REGISTRATION__; // { endpoint, sitekey, site } (config.js)

const events = computed(() => frontmatter.value?.registration?.events ?? []);
const t = computed(() => registrationLabels(lang.value));
const langCode = computed(() => String(lang.value || "es").split(":").pop().slice(0, 2).toLowerCase());

const open = ref(false);
const mode = ref("new"); // "new" | "edit"
const status = ref("idle"); // idle | loading | sending | done | error
const message = ref("");
const emailSent = ref(true);
const form = ref(blank());
const edit = ref(null); // { id, secret, eventLabel }
const turnstileEl = ref(null);
let widgetId = null;
let token = "";

function blank() {
  return { event: "", name: "", phone: "", email: "", people: 1, notes: "", consent: false, website: "" };
}

const selected = computed(() => events.value.find((e) => e.id === form.value.event));
const fmtDate = (iso) => {
  try {
    return new Intl.DateTimeFormat(langCode.value, { dateStyle: "full" }).format(new Date(iso + "T12:00:00"));
  } catch {
    return iso;
  }
};
const WEEKDAYS = { MO: 1, TU: 2, WE: 3, TH: 4, FR: 5, SA: 6, SU: 0 };
const fmtDay = (code) => {
  const n = WEEKDAYS[String(code).toUpperCase()];
  if (n === undefined) return code;
  try {
    return new Intl.DateTimeFormat(langCode.value, { weekday: "long" }).format(new Date(2024, 0, 7 + n));
  } catch {
    return code;
  }
};
const when = computed(() => {
  const e = selected.value;
  if (!e) return "";
  const parts = [];
  if (e.dates?.length) parts.push(e.dates.slice(0, 6).map(fmtDate).join(" · ") + (e.dates.length > 6 ? " …" : ""));
  else if (e.byday?.length) parts.push(e.byday.map(fmtDay).join(", "));
  if (e.times?.length) parts.push(e.times.join(", "));
  return parts.join(" — ");
});

// ---- URL <-> open state ---------------------------------------------------
function setParam(value) {
  const u = new URL(location.href);
  if (value === null) u.searchParams.delete("register");
  else u.searchParams.set("register", value);
  history.replaceState(history.state, "", u);
}

function openForm(eventId = "") {
  mode.value = "new";
  status.value = "idle";
  message.value = "";
  form.value = blank();
  const match = events.value.find((e) => e.id === eventId);
  form.value.event = match ? match.id : events.value.length === 1 ? events.value[0].id : "";
  open.value = true;
  setParam(match ? match.id : "");
}

function closeForm() {
  open.value = false;
  removeWidget();
  const u = new URL(location.href);
  u.searchParams.delete("register");
  u.searchParams.delete("edit");
  history.replaceState(history.state, "", u);
}

function readUrl() {
  const p = new URLSearchParams(location.search);
  if (p.has("edit")) return openEdit(p.get("edit"));
  if (p.has("register") && events.value.length) openForm(p.get("register"));
}

// ---- Turnstile ------------------------------------------------------------
function loadTurnstile() {
  if (window.turnstile) return Promise.resolve(window.turnstile);
  return new Promise((resolve, reject) => {
    const s = document.createElement("script");
    s.src = "https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit";
    s.async = true;
    s.onload = () => resolve(window.turnstile);
    s.onerror = reject;
    document.head.appendChild(s);
  });
}

async function renderWidget() {
  if (mode.value !== "new") return;
  await nextTick();
  if (!turnstileEl.value || widgetId !== null) return;
  try {
    const ts = await loadTurnstile();
    widgetId = ts.render(turnstileEl.value, {
      sitekey: REG.sitekey,
      action: "register",
      language: langCode.value,
      callback: (tk) => (token = tk),
      "expired-callback": () => (token = ""),
      "error-callback": () => (token = ""),
    });
  } catch {
    showError(t.value.errorCaptcha);
  }
}

function removeWidget() {
  if (widgetId !== null && window.turnstile) window.turnstile.remove(widgetId);
  widgetId = null;
  token = "";
}

// Tokens are single use: after every attempt the widget must be reset.
function resetWidget() {
  token = "";
  if (widgetId !== null && window.turnstile) window.turnstile.reset(widgetId);
}

watch(open, (v) => v && renderWidget());

// ---- API ------------------------------------------------------------------
function showError(msg) {
  status.value = "error";
  message.value = msg;
}

function errorFor(res) {
  if (res.status === 429) return t.value.errorRate;
  if (res.status === 403) return t.value.errorCaptcha;
  return t.value.errorGeneric;
}

const payload = () => ({
  name: form.value.name,
  phone: form.value.phone,
  email: form.value.email,
  people: Number(form.value.people),
  notes: form.value.notes,
});

async function submit() {
  if (status.value === "sending") return;
  if (mode.value === "new" && !selected.value) return showError(t.value.chooseEvent);
  status.value = "sending";
  message.value = "";
  try {
    let res;
    if (mode.value === "edit") {
      res = await fetch(`${REG.endpoint}/${edit.value.id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ k: edit.value.secret, ...payload() }),
      });
    } else {
      res = await fetch(REG.endpoint, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          site: REG.site,
          event: selected.value.id,
          eventLabel: selected.value.title,
          ...payload(),
          consent: form.value.consent === true,
          turnstile: token,
          website: form.value.website,
          lang: langCode.value,
          pageUrl: location.origin + location.pathname,
        }),
      });
    }
    const out = await res.json().catch(() => ({}));
    if (!res.ok) {
      resetWidget();
      return showError(errorFor(res));
    }
    emailSent.value = out.emailSent !== false;
    message.value = mode.value === "edit" ? t.value.savedText : "";
    status.value = "done";
    removeWidget();
  } catch {
    resetWidget();
    showError(t.value.errorGeneric);
  }
}

async function openEdit(raw) {
  const [id, secret] = String(raw || "").split(".");
  mode.value = "edit";
  open.value = true;
  status.value = "loading";
  form.value = blank();
  try {
    const res = await fetch(`${REG.endpoint}/${encodeURIComponent(id)}?k=${encodeURIComponent(secret || "")}`);
    if (!res.ok) return showError(t.value.errorInvalidLink);
    const d = await res.json();
    edit.value = { id, secret, eventLabel: d.eventLabel };
    form.value = { ...blank(), event: d.event, name: d.name, phone: d.phone, email: d.email, people: d.people, notes: d.notes || "" };
    status.value = "idle";
  } catch {
    showError(t.value.errorGeneric);
  }
}

async function cancelRegistration() {
  if (!confirm(t.value.cancelConfirm)) return;
  status.value = "sending";
  try {
    const res = await fetch(`${REG.endpoint}/${edit.value.id}?k=${encodeURIComponent(edit.value.secret)}`, { method: "DELETE" });
    if (!res.ok) return showError(errorFor(res));
    message.value = t.value.cancelledText;
    status.value = "done";
    mode.value = "cancelled";
  } catch {
    showError(t.value.errorGeneric);
  }
}

const onKey = (e) => e.key === "Escape" && open.value && closeForm();
onMounted(() => {
  readUrl();
  window.addEventListener("keydown", onKey);
});
onBeforeUnmount(() => {
  window.removeEventListener("keydown", onKey);
  removeWidget();
});
</script>

<template>
  <div v-if="events.length || open">
    <button
      v-if="!open && events.length"
      type="button"
      class="fixed bottom-4 left-4 z-[9990] bg-accent text-white font-medium px-5 py-3 rounded-full shadow-lg"
      @click="openForm(events.length === 1 ? events[0].id : '')"
    >
      {{ t.registerButton }}
    </button>

    <div v-if="open" class="fixed inset-0 z-[9995] flex items-end sm:items-center justify-center bg-black/50 p-0 sm:p-4" @click.self="closeForm">
      <div class="bg-white text-gray-900 w-full sm:max-w-lg max-h-[92vh] overflow-y-auto rounded-t-2xl sm:rounded-2xl p-5 shadow-xl" role="dialog" aria-modal="true">
        <div class="flex items-start justify-between gap-4 mb-3">
          <h2 class="text-xl font-semibold m-0">{{ mode === "edit" ? t.editTitle : t.title }}</h2>
          <button type="button" class="text-2xl leading-none px-2" :aria-label="t.close" @click="closeForm">×</button>
        </div>

        <p v-if="status === 'loading'">{{ t.loading }}</p>

        <div v-else-if="status === 'done'">
          <p v-if="mode === 'new'" class="font-semibold">{{ t.doneTitle }}</p>
          <p v-if="mode === 'new' && emailSent">{{ t.doneText.replace("{email}", form.email) }}</p>
          <p v-else-if="mode === 'new'">{{ t.doneNoMail }}</p>
          <p v-else>{{ message }}</p>
          <button type="button" class="mt-4 bg-accent text-white px-5 py-2 rounded-lg" @click="closeForm">{{ t.close }}</button>
        </div>

        <form v-else-if="mode === 'new' || edit" class="space-y-3" @submit.prevent="submit">
          <!-- Event info (from the page) -->
          <div v-if="mode === 'edit'" class="rounded-lg bg-gray-100 p-3 text-sm">
            <strong>{{ edit.eventLabel }}</strong>
          </div>
          <template v-else>
            <label v-if="events.length > 1" class="block text-sm font-medium">
              {{ t.event }}
              <select v-model="form.event" required class="mt-1 w-full rounded-lg border border-gray-300 px-3 py-2">
                <option value="" disabled>{{ t.chooseEvent }}</option>
                <option v-for="e in events" :key="e.id" :value="e.id">{{ e.title }}</option>
              </select>
            </label>
            <div v-if="selected" class="rounded-lg bg-gray-100 p-3 text-sm space-y-1">
              <div class="font-semibold">{{ selected.title }}</div>
              <div v-if="when"><span class="text-gray-500">{{ t.when }}:</span> {{ when }}</div>
              <div v-if="selected.place"><span class="text-gray-500">{{ t.where }}:</span> {{ selected.place }}</div>
            </div>
          </template>

          <label class="block text-sm font-medium">{{ t.name }}
            <input v-model="form.name" required maxlength="120" autocomplete="name" class="mt-1 w-full rounded-lg border border-gray-300 px-3 py-2" />
          </label>
          <label class="block text-sm font-medium">{{ t.phone }}
            <input v-model="form.phone" required type="tel" maxlength="40" autocomplete="tel" class="mt-1 w-full rounded-lg border border-gray-300 px-3 py-2" />
          </label>
          <label class="block text-sm font-medium">{{ t.email }}
            <input v-model="form.email" required type="email" maxlength="254" autocomplete="email" class="mt-1 w-full rounded-lg border border-gray-300 px-3 py-2" />
          </label>
          <label class="block text-sm font-medium">{{ t.people }}
            <input v-model.number="form.people" required type="number" min="1" max="500" step="1" class="mt-1 w-full rounded-lg border border-gray-300 px-3 py-2" />
          </label>
          <label class="block text-sm font-medium">{{ t.notes }}
            <textarea v-model="form.notes" rows="4" maxlength="2000" class="mt-1 w-full rounded-lg border border-gray-300 px-3 py-2"></textarea>
          </label>

          <!-- Honeypot: invisible to people, tempting to bots -->
          <input v-model="form.website" type="text" name="website" tabindex="-1" autocomplete="off" aria-hidden="true" class="absolute left-[-9999px] h-0 w-0 opacity-0" />

          <label v-if="mode === 'new'" class="flex items-start gap-2 text-sm">
            <input v-model="form.consent" required type="checkbox" class="mt-1" />
            <span>{{ t.consent }} <a href="/aviso-legal-y-politica-de-privacidad" target="_blank" rel="noopener" class="underline">{{ t.privacy }}</a></span>
          </label>

          <div v-if="mode === 'new'" ref="turnstileEl"></div>

          <p v-if="status === 'error'" class="text-red-700 text-sm" role="alert">{{ message }}</p>

          <div class="flex flex-wrap gap-2 pt-1">
            <button type="submit" :disabled="status === 'sending'" class="bg-accent text-white font-medium px-5 py-2 rounded-lg disabled:opacity-60">
              {{ status === "sending" ? t.sending : mode === "edit" ? t.save : t.submit }}
            </button>
            <button v-if="mode === 'edit'" type="button" :disabled="status === 'sending'" class="border border-red-600 text-red-700 px-5 py-2 rounded-lg" @click="cancelRegistration">
              {{ t.cancelReg }}
            </button>
          </div>
        </form>

        <p v-else-if="status === 'error'" class="text-red-700 text-sm" role="alert">{{ message }}</p>
      </div>
    </div>
  </div>
</template>
